import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`pitch-deck-investors`,heroTitle:`Get your investor-ready pitch deck in minutes`,heroSubtitle:`Perplexity Computer reviews your pitch deck, benchmarks it against top-funded startups, and delivers a detailed investor readiness report — automatically.`,heroCta:`Get Started`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Review my pitch deck`,inputFileAccept:`.pdf,.doc,.docx`,inputFilePrefill:`Review the uploaded pitch deck and perform a comprehensive investor readiness audit. 1) Evaluate the deck's structure against best practices from top-funded startups — check for problem, solution, market size, traction, business model, team, competitive landscape, financials, and ask slides. 2) Score each slide on clarity, persuasiveness, and data quality on a 1-10 scale. 3) Research the startup's market using live data — TAM/SAM/SOM estimates, competitor funding rounds, and recent industry trends — and flag where the deck's claims don't hold up. 4) Identify the 5 toughest questions a VC would ask based on gaps in the deck. 5) Deliver a prioritized revision playbook with specific rewrites, missing data points to add, and narrative improvements. 6) Generate a one-page executive summary investors can skim in 30 seconds. 7) Compile everything into a polished investor readiness report with slide-by-slide scores, market validation, VC objection prep, and the revision playbook.`,heroOverlaySteps:[`Analyzing your pitch deck slide by slide`,`Researching your market, competitors, and recent funding data`,`Identifying narrative gaps and tough VC questions`,`Investor readiness report with scores and revision playbook — ready to review`],generatingTitle:`Designing your workflow...`,generatingSteps:[`Parsing the uploaded file to extract slides, claims, and financials`,`Designing an agent to benchmark your deck against top-funded startup pitch decks`,`Configuring market research, competitor analysis, and VC objection detection`,`Setting up your investor readiness report with slide scores and revision playbook`],featureSectionTitle:`From pitch deck to investor readiness report`,featureCardTitles:[`Connects to your startup stack`,`Outputs you can pitch with`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Notion, Slack, Canva — Computer pulls in your data and delivers reports straight to the tools your team already uses.`,`Slide-by-slide scorecards. Market validation with live data. VC objection prep. A prioritized revision playbook. A 30-second executive summary.`],capabilitySectionTitle:`Your pitch coach, on autopilot`,capabilitySectionSubtitle:`Upload your deck, step away, come back to a complete investor readiness strategy.`,capabilityCards:[{title:`Deck Scoring`,description:`Computer can score every slide on clarity, persuasiveness, and data quality — and benchmark your structure against decks that closed real rounds.`},{title:`Market Validation`,description:`Computer can research your TAM, competitor funding rounds, and industry trends — and flag where your deck's claims need stronger evidence.`},{title:`VC Objection Prep`,description:`Computer can identify the toughest questions investors will ask — and draft talking points so you're never caught off guard.`},{title:`Connect Your Tools`,description:`Computer can push reports to Google Drive, Notion, Slack, and Google Sheets — build workflows across your entire fundraising stack.`},{title:`Version Memory`,description:`Computer can remember past deck versions, scores, and feedback across sessions — so every revision tracks your improvement over time.`},{title:`Monitor & Alert`,description:`Computer can track competitor funding news and market shifts — and flag when your deck needs updating to stay current.`}]});export{t as default};
